            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"160\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">TRAVERSE, NEJM 2023</text><text x=\"550\" y=\"275\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">5,246 men with low T</text><text x=\"550\" y=\"320\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">and heart disease or high risk</text><rect x=\"150\" y=\"440\" width=\"380\" height=\"200\" rx=\"20\" fill=\"rgba(59,130,246,0.15)\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"340\" y=\"525\" text-anchor=\"middle\" fill=\"#3b82f6\" font-weight=\"bold\" font-size=\"24\">TESTOSTERONE</text><text x=\"340\" y=\"575\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">heart events?</text><rect x=\"570\" y=\"440\" width=\"380\" height=\"200\" rx=\"20\" fill=\"rgba(139,92,246,0.15)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"760\" y=\"525\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">PLACEBO</text><text x=\"760\" y=\"575\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">heart events?</text><text x=\"550\" y=\"740\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">And what else showed up?</text></svg>",
